#[no_mangle]
pub unsafe extern "C" fn UTF8ToHtml(
    mut out: *mut c_uchar,
    mut outlen: *mut c_int,
    mut in_0: *const c_uchar,
    mut inlen: *mut c_int,
) -> c_int {
    if out.is_null() || outlen.is_null() || inlen.is_null() {
        return -(1 as c_int);
    }
    if in_0.is_null() {
        // SAFETY: outlen and inlen were checked non-null above.
        unsafe {
            *outlen = 0 as c_int;
            *inlen = 0 as c_int;
        }
        return 0 as c_int;
    }

    let outstart = out;
    let instart = in_0;
    let mut processed = in_0;

    // SAFETY: in_0/out are valid pointers per the original function contract; offset uses caller-provided lengths exactly as before.
    let inend = unsafe { in_0.offset(*inlen as isize) };
    // SAFETY: out is valid per the original function contract; offset uses caller-provided length exactly as before.
    let outend = unsafe { out.offset(*outlen as isize) };

    while in_0 < inend {
        // SAFETY: loop invariant guarantees in_0 < inend, so dereference is in-bounds.
        let d0 = unsafe {
            let p = in_0;
            in_0 = in_0.offset(1);
            *p as c_uint
        };

        let mut c: c_uint;
        let mut trailing: c_int;

        if d0 < 0x80 {
            c = d0;
            trailing = 0;
        } else if d0 < 0xc0 {
            // SAFETY: outlen/inlen are non-null; pointer differences are within the same allocations as in the original code.
            unsafe {
                *outlen = out.offset_from(outstart) as c_long as c_int;
                *inlen = processed.offset_from(instart) as c_long as c_int;
            }
            return -2;
        } else if d0 < 0xe0 {
            c = d0 & 0x1f;
            trailing = 1;
        } else if d0 < 0xf0 {
            c = d0 & 0x0f;
            trailing = 2;
        } else if d0 < 0xf8 {
            c = d0 & 0x07;
            trailing = 3;
        } else {
            // SAFETY: outlen/inlen are non-null; pointer differences are within the same allocations as in the original code.
            unsafe {
                *outlen = out.offset_from(outstart) as c_long as c_int;
                *inlen = processed.offset_from(instart) as c_long as c_int;
            }
            return -2;
        }

        // Fast path for ASCII.
        if trailing == 0 {
            if c < 0x80 {
                // SAFETY: pointer arithmetic mirrors the original bounds check.
                if unsafe { out.offset(1) } >= outend {
                    break;
                }
                // SAFETY: bounds check above ensures one byte is writable.
                unsafe {
                    *out = c as c_uchar;
                    out = out.offset(1);
                }
                processed = in_0;
                continue;
            }
        } else {
            // SAFETY: offset_from on pointers into the same input allocation, as in the original code.
            if unsafe { inend.offset_from(in_0) as c_long } < trailing as c_long {
                break;
            }

            let mut ok = true;
            while trailing != 0 {
                if in_0 >= inend {
                    ok = false;
                    break;
                }
                // SAFETY: in_0 < inend checked just above, so dereference is in-bounds.
                let d = unsafe {
                    let p = in_0;
                    in_0 = in_0.offset(1);
                    *p as c_uint
                };
                if d & 0xc0 != 0x80 {
                    ok = false;
                    break;
                }
                c = (c << 6) | (d & 0x3f);
                trailing -= 1;
            }
            if !ok {
                break;
            }
        }

        if c < 0x80 {
            // SAFETY: pointer arithmetic mirrors the original bounds check.
            if unsafe { out.offset(1) } >= outend {
                break;
            }
            // SAFETY: bounds check above ensures one byte is writable.
            unsafe {
                *out = c as c_uchar;
                out = out.offset(1);
            }
        } else {
            let mut nbuf: [c_char; 16] = [0; 16];
            // SAFETY: external lookup is called exactly as in the original code.
            let ent = unsafe { htmlEntityValueLookup(c) };
            let cp: *const c_char = if ent.is_null() {
                // SAFETY: nbuf is a valid writable buffer of the provided size; format string is NUL-terminated and arguments match.
                unsafe {
                    snprintf(
                        nbuf.as_mut_ptr(),
                        ::core::mem::size_of::<[c_char; 16]>() as size_t,
                        b"#%u\0" as *const u8 as *const c_char,
                        c,
                    );
                }
                nbuf.as_mut_ptr()
            } else {
                // SAFETY: ent is non-null and points to a valid htmlEntityDesc per lookup contract.
                unsafe { (*ent).name }
            };

            // SAFETY: cp is a valid NUL-terminated string from either snprintf into nbuf or entity table.
            let len = unsafe { strlen(cp) as c_int };

            // SAFETY: pointer arithmetic mirrors the original bounds check.
            if unsafe { out.offset(2).offset(len as isize) } >= outend {
                break;
            }

            // SAFETY: bounds check above ensures space for '&', len bytes, and ';'; memcpy source/destination are valid and non-overlapping as in original usage.
            unsafe {
                *out = b'&' as c_uchar;
                out = out.offset(1);
                memcpy(out as *mut c_void, cp as *const c_void, len as size_t);
                out = out.offset(len as isize);
                *out = b';' as c_uchar;
                out = out.offset(1);
            }
        }

        processed = in_0;
    }

    // SAFETY: outlen/inlen are non-null; pointer differences are within the same allocations as in the original code.
    unsafe {
        *outlen = out.offset_from(outstart) as c_long as c_int;
        *inlen = processed.offset_from(instart) as c_long as c_int;
    }
    0 as c_int
}

